require_relative 'driver'
# Same 2400px production canvas, aspect5 bounds cost while preserving public behavior.
W='work(m,{pile=p,seed=7})'
{'base'=>'','loadlow'=>'load=0.1','loadhigh'=>'load=0.8','round'=>'tool="round 2",pressure={0.2,0.2}','filbert'=>'tool="filbert 12",pressure={0.8,0.8}','coverage'=>'coverage=0.1,fill=false','fill'=>'coverage=0.1,fill=true','angle'=>'angle=1.57079632679','field'=>'angle=function(x,y) samples=(samples or 0)+1;return x/1000 end','loadfield'=>'load_at=function(x,y)return x<400 and 0.1 or 0.8 end','across'=>'order="across"','down'=>'order="down"','scatter'=>'order="scatter"','lost'=>'edge="lost"','cutin'=>'cut_in="round 2"'}.each{|k,o|case_image('pass-'+k,'',"work(m,{pile=p,seed=7,#{o}});print(wait(0),samples)")}
case_image('pass-stipple','', 'stipple(m,{pile=p,width=2,coverage=0.5,seed=7});print(wait(0))')
case_image('pass-stipple-var','', 'stipple(m,{pile=p,width=6,coverage=0.5,cluster=0.8,feather=0.8,drag={3,0},twist=0.5,seed=7});print(wait(0))')
case_image('pass-lose','', 'print(lose(m,{pile=p,where=1,reach={30,10},load=0.2,seed=7}));print(wait(0))')
fresh('pass-validation');shot('pass-validation-before');['work(7,{pile=p})','work(m,{pile=7})','work(m,{pile=p,edge="lost",cut_in="round 2"})','pile{{"not a tube",1}}','work(rect(0,0,0,0),{pile=p,covrage=1})','work(rect(0,0,1,1),{pile=p,covrage=1})','work(m,{pile=p,angle=function()error("field failure")end})','undo()'].each{|c|run(c)};shot('pass-validation-after');run('print(wait(0));'+W+';marker=12;print(wait(0))');shot('pass-once');run('print(marker);'+W+';print(wait(0))');shot('pass-twice');run('local hiddenmask=rect(0,0,10,10);local hiddenpile=pile{{"bone black",1}}');run('print(hiddenmask,hiddenpile,type(m),type(p))');run('b=brush("round",2);b:load(p);for i=1,100 do b:touch(100+i,20) end;'+W);run(W+';'+W)
# Aging four stages at a painted point, independent materials/loads and post-dry overlays.
%w[red-earth raw-umber lead-white bone-black].each{|mat|fresh('age-'+mat,"p=pile{{\"#{mat.tr('-',' ')}\",1}};b=brush(\"flat\",50);b:load(p);b:touch(400,80);");run('print(wait(0),drying(400,80));for _,n in ipairs{5,10,15,30,60,120,240,480,960,1440,2880,5760} do print(wait(n),drying(400,80)) end')}
[false,true].each{|aged|case_image('layer-'+aged.to_s,'work(m,{pile=p,hand="detail",coverage=2,clip=true,seed=1});'+(aged ? 'wait(43200);' : '')+'print(drying(400,80));','b=brush("round",20);b:load(q);b:stroke({{200,80},{600,80}},{shake=0});print(drying(400,80))')}
fresh('clock');run('r=rag{width=20};r:dip(1);print(wait(0),r.damp);p1=pile{{"red earth",1},{"lead white",1}};print(wait(0),r.damp);p2=pile{{"red earth",2},{"lead white",1}};print(wait(0),r.damp);p3=pile{{"red earth",3},{"lead white",1}};print(drying(400,80),wait(0),r.damp)');run('b=brush("round",4);r:dip(1);print(r.damp);b:load(p1);print(wait(0),r.damp);r:dip(1);b:load(p1);print(wait(0),r.damp)');run('print(wait(1));print(wait(2))');run('print(wait(5259600));print(wait(1))');run('wait(5259601)');run('wait(0/0)')
# Time continuous observable: dampness halves every3 min, so elapsed sec=-180*log2(after/before).
fresh('ledger');run('b=brush("round",4);r=rag{width=20};r:dip(1);print(wait(0),r.damp);for i=1,17 do _G["p"..i]=pile{{"lead white",i},{"red earth",18-i}} end;print(wait(0),r.damp);r:dip(1);print(wait(0),r.damp);b:load(p17);print(wait(0),r.damp);r:dip(1);print(wait(0),r.damp);b:load(p1);print(wait(0),r.damp,type(p1))')
cli('close')
